//! What a mail body carries that the reader warns about: tracking pixels
//! (open-tracking beacons) and unsafe links, plus the safety verdicts a list
//! row wears. Every UI shell asks the daemon (`body.scan`, `body.verdicts`,
//! `body.classify_links`; `src-daemon/src/handlers/body.rs`) and renders the
//! answer; nothing here touches the network.
//!
//! Ported from the app's JS (`trackerList.js`, `trackerDetect.js`,
//! `linkSafety.js`, `rowAlerts.js`, `replyToCheck.js`) and held to it by a
//! golden corpus of that JS's answers (`tests/fixtures/body-scan-cases.json`,
//! regenerated by `tests/fixtures/gen/body-scan-fixtures.mjs`): the verdicts
//! field for field, the rewritten HTML byte for byte.
//!
//! - Trackers: every `<img src>` is checked against the bundled vendor table
//!   ([`tracker_list`]), then, only when no vendor matched and the URL is not
//!   a layout spacer, by shape (at most 3x3, hidden by CSS, or inside a hidden
//!   container) and by request path. A found beacon is replaced by a visible
//!   marker naming the vendor, never the beacon's host. Detection runs for
//!   everyone; the caller decides whether the cleaned body is the one shown
//!   (tracker blocking is premium).
//! - Links: every scannable `<a href>` gets its destination as its title; a
//!   `javascript:`/`data:` link, or text that shows one site and goes to
//!   another, is red; a redirect through one site to another is yellow.
//! - Text the reader sees (reasons, the marker's label and hover text) is
//!   written from templates the app sends in the UI language: the daemon has
//!   no catalogs.

mod dom;
mod js_regex;
mod tracker_list;
#[cfg(test)]
mod tests;

use crate::sender_check::{clean_name, js_space, js_trim, looks_like_address, looks_like_domain};
use dom::Dom;
use js_regex::{compile_i, js_units, translate};
use regex::{Regex, RegexSet};
use serde::Serialize;
use serde_json::{json, Map, Value};
use std::collections::HashMap;
use std::sync::LazyLock;

/// The catalog keys whose templates a scan writes with.
pub const TEXT_KEYS: &[&str] = &[
    K_EXPLAIN, K_LABEL, K_VENDOR, K_PATH, K_HIDDEN_CSS, K_HIDDEN_CONTAINER, K_INVISIBLE, K_SCHEME, K_MISMATCH, K_REDIRECT,
];
const K_EXPLAIN: &str = "util.trackerDetect.blockedExplain";
const K_LABEL: &str = "util.trackerDetect.blockedLabel";
const K_VENDOR: &str = "util.trackerDetect.vendorBeacon";
const K_PATH: &str = "util.trackerDetect.beaconPath";
const K_HIDDEN_CSS: &str = "util.trackerDetect.imageHiddenCssSoNever";
const K_HIDDEN_CONTAINER: &str = "util.trackerDetect.imageHiddenInsideCollapsedContainer";
const K_INVISIBLE: &str = "util.trackerDetect.invisibleImageReadReceiptPicture";
const K_SCHEME: &str = "linkSafety.reason.dangerousScheme";
const K_MISMATCH: &str = "linkSafety.reason.textMismatch";
const K_REDIRECT: &str = "linkSafety.reason.redirect";

/// The UI language's templates, by catalog key, as the app's `t()` holds
/// them (`{{name}}` slots). A key the app did not send reads as the key, as
/// `t()` answers for a key it does not know.
#[derive(Debug, Clone, Default)]
pub struct Texts(HashMap<String, String>);

impl Texts {
    pub fn from_value(v: Option<&Value>) -> Texts {
        let map = v
            .and_then(Value::as_object)
            .map(|o| o.iter().filter_map(|(k, v)| v.as_str().map(|s| (k.clone(), s.to_string()))).collect())
            .unwrap_or_default();
        Texts(map)
    }

    fn template<'a>(&'a self, key: &'a str) -> &'a str {
        self.0.get(key).map(String::as_str).unwrap_or(key)
    }

    /// `t(key, vars)`: each `{{name}}` with a value is replaced, once, left to right.
    fn t(&self, key: &str, vars: &[(&str, &str)]) -> String {
        let s = self.template(key);
        let mut out = String::with_capacity(s.len() + 16);
        let mut rest = s;
        while let Some(at) = rest.find("{{") {
            out.push_str(&rest[..at]);
            let after = &rest[at + 2..];
            let name_len = after.bytes().take_while(|b| b.is_ascii_alphanumeric() || *b == b'_').count();
            if name_len > 0 && after[name_len..].starts_with("}}") {
                let name = &after[..name_len];
                match vars.iter().find(|(k, _)| *k == name) {
                    Some((_, v)) => out.push_str(v),
                    None => out.push_str(&rest[at..at + 2 + name_len + 2]),
                }
                rest = &after[name_len + 2..];
            } else {
                out.push('{');
                rest = &rest[at + 1..];
            }
        }
        out.push_str(rest);
        out
    }
}

// ── trackers ────────────────────────────────────────────────────────────────

/// One beacon found in a body.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Tracker {
    /// The vendor's label, else the beacon's host, else "Unknown sender".
    pub vendor: String,
    /// The vendor table named it.
    pub known: bool,
    pub domain: String,
    pub url: String,
    pub reason: String,
}

/// The persisted shape: small enough to keep for every message ever opened,
/// complete enough to name the tracker on a list row.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Summary {
    pub count: usize,
    pub vendors: Vec<String>,
}

pub fn summarize(trackers: &[Tracker]) -> Option<Summary> {
    if trackers.is_empty() {
        return None;
    }
    let mut vendors: Vec<String> = Vec::new();
    for t in trackers {
        if !vendors.contains(&t.vendor) {
            vendors.push(t.vendor.clone());
        }
    }
    Some(Summary { count: trackers.len(), vendors })
}

#[derive(Debug, Clone, PartialEq)]
pub struct TrackerScan {
    pub trackers: Vec<Tracker>,
    /// The body with every beacon replaced by its marker; `None` when nothing
    /// was found, so an unchanged body stays byte-identical.
    pub cleaned: Option<String>,
    /// Remote images the frame may fetch (https only: the app's CSP allows no other).
    pub https: usize,
}

struct Table {
    labels: Vec<&'static str>,
    set: RegexSet,
}

static TABLE: LazyLock<Table> = LazyLock::new(|| {
    let all = tracker_list::CURATED.iter().chain(tracker_list::UGLY_EMAIL).chain(tracker_list::MTB);
    let (labels, sources): (Vec<&'static str>, Vec<String>) = all.map(|(l, s)| (*l, format!("(?i-u:{})", translate(s)))).unzip();
    Table { labels, set: RegexSet::new(sources).expect("tracker table compiles") }
});

/// How many endpoint rules the bundled table holds (the settings page says so).
pub fn tracker_pattern_count() -> usize {
    tracker_list::CURATED.len() + tracker_list::UGLY_EMAIL.len() + tracker_list::MTB.len()
}

/// Path segments that only ever belong to a beacon, not to artwork.
static BEACON_PATH: LazyLock<Regex> = LazyLock::new(|| {
    compile_i(r"\/(open|opens|beacon|pixel|track|tracking|trk|impression)(\.(gif|png|jpg|jpeg|webp))?(\/|\?|$)|\/o\/|\/q\/|\/wf\/open|open\.(gif|png|aspx|php)")
});
/// Images that are legitimately tiny or hidden (MailTrackerBlocker's own false-positive guard).
static SPACER_ALLOWLIST: LazyLock<Regex> = LazyLock::new(|| {
    compile_i(r"spacer|transparent\.gif|blank\.gif|pixel\.gif\?$|attachments\.office\.net\/owa\/|apple_logo_web|sidebar-gradient|fedex_collective_logo_")
});
/// Inline styles that put an image out of sight, but for `opacity:0`
/// (JS: `opacity\s*:\s*0(?!\.)`, a lookahead the regex crate has not: see [`hidden_style`]).
static HIDDEN_STYLE: LazyLock<Regex> = LazyLock::new(|| compile_i(r"display\s*:\s*none|visibility\s*:\s*hidden|max-height\s*:\s*0"));
static OPACITY_ZERO: LazyLock<Regex> = LazyLock::new(|| compile_i(r"opacity\s*:\s*0"));
static STYLE_WIDTH: LazyLock<Regex> = LazyLock::new(|| compile_i(r"(?:^|;)\s*width\s*:\s*([^;]+)"));
static STYLE_HEIGHT: LazyLock<Regex> = LazyLock::new(|| compile_i(r"(?:^|;)\s*height\s*:\s*([^;]+)"));

const MARKER_STYLE: &str = "display:inline-block;margin:2px 0;padding:0 6px;border-radius:4px;\
font:11px/18px -apple-system,system-ui,sans-serif;color:#b45309;background:rgba(245,158,11,.12);\
outline:2px solid rgba(245,158,11,.3);outline-offset:1px;cursor:help;white-space:nowrap;";

fn hidden_style(style: &str) -> bool {
    let s = js_units(style);
    if HIDDEN_STYLE.is_match(&s) {
        return true;
    }
    // `opacity\s*:\s*0(?!\.)`: a zero opacity, not 0.5. The `\s*` cannot move
    // where the 0 sits, so each "opacity" has one candidate to check.
    OPACITY_ZERO.find_iter(&s).any(|m| !s[m.end()..].starts_with('.'))
}

/// `new URL(url).hostname.toLowerCase()`, or "" when it does not parse.
fn host_of(url: &str) -> String {
    url::Url::parse(url).map(|u| u.host_str().unwrap_or("").to_lowercase()).unwrap_or_default()
}

/// `^(\d+(?:\.\d+)?)\s*(px)?$` (case-blind) on the trimmed value, as a number.
fn px_value(raw: Option<&str>) -> Option<f64> {
    let s = js_trim(raw?);
    let int = s.bytes().take_while(u8::is_ascii_digit).count();
    if int == 0 {
        return None;
    }
    let mut end = int;
    let b = s.as_bytes();
    if b.get(end) == Some(&b'.') {
        let frac = s[end + 1..].bytes().take_while(u8::is_ascii_digit).count();
        if frac > 0 {
            end += 1 + frac;
        }
    }
    let number = &s[..end];
    let rest = s[end..].trim_start_matches(js_space);
    if !(rest.is_empty() || rest.eq_ignore_ascii_case("px")) {
        return None;
    }
    number.parse().ok()
}

/// `String(n)` for a finite, non-negative number.
fn js_number(n: f64) -> String {
    if n == 0.0 {
        return "0".to_string();
    }
    let sci = format!("{n:e}");
    let (mantissa, exp) = sci.split_once('e').expect("{:e} has an exponent");
    let exp: i32 = exp.parse().expect("exponent");
    if (-6..21).contains(&exp) {
        return format!("{n}");
    }
    format!("{mantissa}e{}{}", if exp < 0 { '-' } else { '+' }, exp.abs())
}

fn style_px(re: &Regex, style: &str) -> Option<f64> {
    let s = js_units(style);
    px_value(re.captures(&s).and_then(|c| c.get(1)).map(|m| m.as_str()))
}

/// Is this `<img>` a beacon by shape: too small to see, or hidden outright?
fn shape_reason(dom: &Dom, img: dom::Id, texts: &Texts) -> Option<String> {
    let style = dom.attr(img, "style").unwrap_or("");
    let w = style_px(&STYLE_WIDTH, style).or_else(|| px_value(dom.attr(img, "width")));
    let h = style_px(&STYLE_HEIGHT, style).or_else(|| px_value(dom.attr(img, "height")));
    if let (Some(w), Some(h)) = (w, h) {
        if w <= 3.0 && h <= 3.0 {
            return Some(texts.t(K_INVISIBLE, &[("w", js_number(w).as_str()), ("h", js_number(h).as_str())]));
        }
    }
    if hidden_style(style) {
        return Some(texts.t(K_HIDDEN_CSS, &[]));
    }
    // `img.closest('[style*="display"], [style*="visibility"], [style*="opacity"]')`:
    // the image itself first, then its ancestors; only a container counts.
    let mut at = Some(img);
    while let Some(id) = at {
        if let Some(s) = dom.attr(id, "style") {
            if s.contains("display") || s.contains("visibility") || s.contains("opacity") {
                if id != img && hidden_style(s) {
                    return Some(texts.t(K_HIDDEN_CONTAINER, &[]));
                }
                return None;
            }
        }
        at = dom.parent_element(id);
    }
    None
}

/// Scan a body (inner body HTML, CID-resolved is fine) for tracking pixels.
pub fn scan_trackers(html: &str, texts: &Texts) -> TrackerScan {
    let mut out = TrackerScan { trackers: Vec::new(), cleaned: None, https: 0 };
    if html.is_empty() {
        return out;
    }
    let mut dom = Dom::parse_body(html);
    for img in dom.select("img", "src") {
        let url = dom.attr(img, "src").unwrap_or("").to_string();
        // Inline and embedded images never leave the machine.
        if url.is_empty() || url.starts_with("cid:") || url.starts_with("data:") || url.starts_with("blob:") {
            continue;
        }
        if url.get(..6).is_some_and(|p| p.eq_ignore_ascii_case("https:")) {
            out.https += 1;
        }
        let domain = host_of(&url);
        let units = js_units(&url);
        let vendor = TABLE.set.matches(&units).iter().next().map(|i| TABLE.labels[i]);
        let reason = match vendor {
            Some(label) => texts.t(K_VENDOR, &[("vendor", label)]),
            None => {
                // Only the heuristics can mistake a real image for a beacon, so
                // the spacer allowlist guards them and not the vendor pass.
                if SPACER_ALLOWLIST.is_match(&units) {
                    continue;
                }
                match shape_reason(&dom, img, texts) {
                    Some(shape) => shape,
                    None if !domain.is_empty() && BEACON_PATH.is_match(&units) => texts.t(K_PATH, &[]),
                    None => continue,
                }
            }
        };
        // A marker where the beacon was, named by vendor and never by host, so
        // the tracker's address is gone from the document.
        let marker = dom.create_element("span");
        dom.set_attr(marker, "data-mv-tracker-blocked", vendor.unwrap_or("tracker"));
        dom.set_attr(marker, "title", &format!("{}\n{}", texts.t(K_EXPLAIN, &[]), reason));
        dom.set_attr(marker, "style", MARKER_STYLE);
        dom.append_text(marker, &format!("\u{1F6E1} {}", texts.t(K_LABEL, &[])));
        dom.replace(img, marker);
        out.trackers.push(Tracker {
            vendor: vendor.map(str::to_string).unwrap_or_else(|| if domain.is_empty() { "Unknown sender".to_string() } else { domain.clone() }),
            known: vendor.is_some(),
            domain,
            url,
            reason,
        });
    }
    if !out.trackers.is_empty() {
        out.cleaned = Some(dom.body_inner_html());
    }
    out
}

// ── links ───────────────────────────────────────────────────────────────────

/// Known legitimate URL shorteners: exempt from yellow.
const SHORTENER_ALLOWLIST: &[&str] = &["bit.ly", "t.co", "goo.gl", "tinyurl.com", "lnkd.in", "ow.ly", "buff.ly", "is.gd", "rb.gy", "cutt.ly"];
static REDIRECT_PARAM: LazyLock<Regex> = LazyLock::new(|| compile_i(r"[?&](?:url|redirect|goto|target|link|dest|destination)=([^&]+)"));

/// One link's verdict.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Classified {
    /// "red", "yellow", or none.
    pub level: Option<&'static str>,
    pub reason: String,
    /// The destination's host: `None` when it does not parse, "" when it has none.
    pub actual_domain: Option<String>,
    /// The host the link's text shows, when it looks like a URL and has one.
    pub text_domain: Option<String>,
}

/// `new URL(s)` (with `https://` before a `www.` address), its host lowercased.
fn extract_domain(s: &str) -> Option<String> {
    let parsed = if s.starts_with("www.") { url::Url::parse(&format!("https://{s}")) } else { url::Url::parse(s) };
    parsed.ok().map(|u| u.host_str().unwrap_or("").to_lowercase())
}

/// `decodeURIComponent`: strict, `None` where it throws (a bad escape, or bytes that are not UTF-8).
fn decode_uri_component(s: &str) -> Option<String> {
    if !s.contains('%') {
        return Some(s.to_string());
    }
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' {
            let hex = s.get(i + 1..i + 3).filter(|h| h.bytes().all(|c| c.is_ascii_hexdigit()))?;
            out.push(u8::from_str_radix(hex, 16).ok()?);
            i += 3;
        } else {
            out.push(b[i]);
            i += 1;
        }
    }
    String::from_utf8(out).ok()
}

/// Whether a link is worth classifying: a web address or a script/data
/// scheme. Anchors, `cid:`, `mailto:`, `tel:` and relative links are not.
pub fn is_scannable_href(href: &str) -> bool {
    !(href.is_empty()
        || href.starts_with('#')
        || href.starts_with("cid:")
        || href.starts_with("mailto:")
        || href.starts_with("tel:")
        || (!href.contains("://") && !href.starts_with("javascript:") && !href.starts_with("data:")))
}

/// The verdict on one link (`href` as written, `text` its trimmed text).
pub fn classify_link(href: &str, text: &str, texts: &Texts) -> Classified {
    let actual = extract_domain(href);
    let shown = js_trim(text);
    let text_domain = if shown.contains("://") || shown.starts_with("www.") { extract_domain(text) } else { None };
    let filled = |d: &Option<String>| d.as_deref().filter(|d| !d.is_empty()).map(str::to_string);
    let (shown_domain, actual_domain) = (filled(&text_domain), filled(&actual));
    let (level, reason) = if href.starts_with("javascript:") || href.starts_with("data:") {
        (Some("red"), texts.t(K_SCHEME, &[("scheme", href.split(':').next().unwrap_or(""))]))
    } else if let Some(reason) = match (&shown_domain, &actual_domain) {
        (Some(t), Some(a)) if t != a => Some(texts.t(K_MISMATCH, &[("textDomain", t.as_str()), ("actualDomain", a.as_str())])),
        _ => None,
    } {
        (Some("red"), reason)
    } else {
        redirect_verdict(href, actual_domain, texts).map_or((None, String::new()), |r| (Some("yellow"), r))
    };
    Classified { level, reason, actual_domain: actual, text_domain: shown_domain }
}

fn redirect_verdict(href: &str, actual: Option<String>, texts: &Texts) -> Option<String> {
    let actual = actual?;
    if SHORTENER_ALLOWLIST.contains(&actual.as_str()) {
        return None;
    }
    let target = REDIRECT_PARAM.captures(href)?.get(1)?.as_str();
    let redirect_domain = extract_domain(&decode_uri_component(target)?).filter(|d| !d.is_empty())?;
    (redirect_domain != actual).then(|| texts.t(K_REDIRECT, &[("actualDomain", actual.as_str()), ("redirectDomain", redirect_domain.as_str())]))
}

/// A flagged link, as the reader's tooltip and the link-safety dialog list it.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LinkAlert {
    pub level: &'static str,
    pub text_content: String,
    pub text_domain: Option<String>,
    pub actual_url: String,
    pub actual_domain: Option<String>,
    pub reason: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct LinkScan {
    pub alerts: Vec<LinkAlert>,
    /// The body with every scannable link titled with its destination (or its
    /// reason) and every flagged one marked `data-link-alert`.
    pub html: String,
    pub max_level: Option<&'static str>,
}

/// Scan a body for suspicious links.
pub fn scan_links(html: &str, texts: &Texts) -> LinkScan {
    let mut out = LinkScan { alerts: Vec::new(), html: String::new(), max_level: None };
    if html.is_empty() {
        return out;
    }
    let mut dom = Dom::parse_body(html);
    for link in dom.select("a", "href") {
        let href = dom.attr(link, "href").unwrap_or("").to_string();
        let text = js_trim(&dom.text_content(link)).to_string();
        if !is_scannable_href(&href) {
            continue;
        }
        // Every link shows where it goes on hover.
        if dom.attr(link, "title").map_or(true, str::is_empty) {
            dom.set_attr(link, "title", &href);
        }
        let verdict = classify_link(&href, &text, texts);
        if let Some(level) = verdict.level {
            dom.set_attr(link, "data-link-alert", level);
            dom.set_attr(link, "title", &verdict.reason);
            if out.max_level.is_none() || level == "red" {
                out.max_level = Some(level);
            }
            out.alerts.push(LinkAlert {
                level,
                text_content: text,
                text_domain: verdict.text_domain,
                actual_url: href,
                actual_domain: verdict.actual_domain,
                reason: verdict.reason,
            });
        }
    }
    out.html = dom.body_inner_html();
    out
}

// ── the reader's scan ───────────────────────────────────────────────────────

/// What the reader frames: the tracker scan of `html`; the body it shows
/// (the cleaned one when `blocking`); and, when `links`, that body's link scan.
/// `html` in the answer is the body to frame, `null` when it is `html` itself.
pub fn scan_body(html: &str, blocking: bool, links: bool, texts: &Texts) -> Value {
    let found = scan_trackers(html, texts);
    let shown: &str = match (&found.cleaned, blocking) {
        (Some(cleaned), true) => cleaned,
        _ => html,
    };
    let (framed, alerts, max_level) = if links {
        let scan = scan_links(shown, texts);
        (Some(scan.html), Some(scan.alerts), scan.max_level)
    } else {
        (found.cleaned.clone().filter(|_| blocking), None, None)
    };
    json!({
        "trackers": found.trackers,
        "count": found.trackers.len(),
        "https": found.https,
        "summary": summarize(&found.trackers),
        "html": framed,
        "alerts": alerts,
        "maxAlertLevel": max_level,
    })
}

// ── list rows ───────────────────────────────────────────────────────────────

/// A JavaScript truthiness test on a JSON value.
fn truthy(v: Option<&Value>) -> bool {
    match v {
        None | Some(Value::Null) | Some(Value::Bool(false)) => false,
        Some(Value::String(s)) => !s.is_empty(),
        Some(Value::Number(n)) => n.as_f64().is_some_and(|f| f != 0.0),
        _ => true,
    }
}

fn str_at<'a>(v: &'a Value, path: &[&str]) -> &'a str {
    let mut at = v;
    for p in path {
        match at.get(p) {
            Some(next) => at = next,
            None => return "",
        }
    }
    at.as_str().unwrap_or("")
}

fn domain_part(address: &str) -> String {
    address.to_lowercase().split('@').nth(1).unwrap_or("").to_string()
}

/// A Reply-To that leads to a domain other than (and unrelated to) the
/// sender's: `{fromDomain, replyToAddress, replyToDomain}`.
pub fn reply_to_mismatch(row: &Value) -> Option<Value> {
    let from_domain = domain_part(str_at(row, &["from", "address"]));
    if from_domain.is_empty() {
        return None;
    }
    let reply_to = match row.get("replyTo") {
        Some(Value::Array(list)) => list.first().map(|r| str_at(r, &["address"])).unwrap_or(""),
        Some(Value::String(s)) => s.as_str(),
        Some(other) => str_at(other, &["address"]),
        None => "",
    };
    let reply_domain = domain_part(reply_to);
    if reply_domain.is_empty()
        || reply_domain == from_domain
        || from_domain.ends_with(&format!(".{reply_domain}"))
        || reply_domain.ends_with(&format!(".{from_domain}"))
    {
        return None;
    }
    Some(json!({"fromDomain": from_domain, "replyToAddress": reply_to, "replyToDomain": reply_domain}))
}

/// A display name dressed as an address (red) or a domain (yellow) that the
/// sending address does not belong to.
pub fn sender_alert(row: &Value) -> Option<&'static str> {
    let addr = str_at(row, &["from", "address"]).to_lowercase();
    if addr.is_empty() {
        return None;
    }
    let addr_domain = addr.split('@').nth(1).unwrap_or("");
    let name = clean_name(str_at(row, &["from", "name"]));
    if name.is_empty() {
        return None;
    }
    let lower = name.to_lowercase();
    let related = |a: &str, b: &str| a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"));
    if looks_like_address(&name) && lower != addr {
        let name_domain = lower.split('@').nth(1).unwrap_or("");
        return (!related(addr_domain, name_domain)).then_some("red");
    }
    (looks_like_domain(&lower) && !related(addr_domain, &lower)).then_some("yellow")
}

/// The persisted verdicts and the reading toggle a row's alerts depend on,
/// from the settings document (`mailvault-settings`).
#[derive(Debug, Clone, Default)]
pub struct RowSettings {
    pub link_safety_enabled: bool,
    pub link_alerts: Map<String, Value>,
    pub tracker_alerts: Map<String, Value>,
}

impl RowSettings {
    /// From the app's settings store state (`{linkSafetyEnabled, linkAlerts, trackerAlerts}`).
    pub fn from_state(state: &Value) -> RowSettings {
        let map = |k: &str| state.get(k).and_then(Value::as_object).cloned().unwrap_or_default();
        RowSettings { link_safety_enabled: truthy(state.get("linkSafetyEnabled")), link_alerts: map("linkAlerts"), tracker_alerts: map("trackerAlerts") }
    }
}

/// The alerts a list row wears, as the fields the row gains: `_linkAlert` and
/// `_trackerInfo` (persisted, by the row's scoped key), `_senderAlert` and
/// `_replyToMismatch` (when link safety is on). A field the row already
/// carries is never answered, so a verdict a row holds is never replaced.
pub fn row_alerts(row: &Value, key: Option<&str>, settings: &RowSettings) -> Map<String, Value> {
    let mut out = Map::new();
    if let Some(key) = key {
        if !truthy(row.get("_linkAlert")) && truthy(settings.link_alerts.get(key)) {
            out.insert("_linkAlert".into(), settings.link_alerts[key].clone());
        }
        if !truthy(row.get("_trackerInfo")) && truthy(settings.tracker_alerts.get(key)) {
            out.insert("_trackerInfo".into(), settings.tracker_alerts[key].clone());
        }
    }
    if !settings.link_safety_enabled {
        return out;
    }
    if row.get("_senderAlert").is_none() {
        if let Some(level) = sender_alert(row) {
            out.insert("_senderAlert".into(), Value::String(level.into()));
        }
    }
    if row.get("_replyToMismatch").is_none() {
        if let Some(m) = reply_to_mismatch(row) {
            out.insert("_replyToMismatch".into(), m);
        }
    }
    out
}
